// Build Test Plan
// Defines every automated test case with its payload and expected result.
// A run ID is added to every event ID and email so each run is independent of earlier runs.

const settings = $('Test Settings').first().json;
const run = 't' + Date.now().toString(36).slice(-6);
const mail = (local, domain) => `${local}+${run}@${domain}`;
const ev = (id) => `${run}-${id}`;

const cases = [
