    expect: { event: 'routed', priority: 'Warm', score: 55, pool: 'east', route_type: 'territory', lead: { budget_band: '$15k-$50k' } },
  },
  {
    id: 'TC-10', batch: 'A', title: 'West lead for round-robin balance',
    payload: { event_id: ev('TC-10'), first_name: 'Isabella', last_name: 'Rossi', email: mail('isabella.rossi', 'sunsetvet.example.com'), phone: '(602) 555-0110', company: 'Sunset Veterinary Clinic', job_title: 'Practice Manager', state: 'AZ', country: 'US', company_size: '11-50', budget: '$5k-$15k', service_interest: 'Cybersecurity', timeline: 'ASAP' },
