    payload: { event_id: ev('TC-13'), first_name: 'Jacob', last_name: 'Reed', email: mail('jacob.reed', 'reedfamilyfarms.example.com'), company: '', service_interest: '', state: 'IA' },
    expect: { event: 'rejected', reason_includes: 'Missing company; Missing service interest' },
  },
  {
