    repeat: 2,
    payload: { submitted_at: '2026-10-05T15:00:00Z', first_name: 'Zoe', last_name: 'Carter', email: mail('zoe.carter', 'lakesidelaw.example.com'), phone: '(206) 555-0115', company: 'Lakeside Law Group', job_title: 'Managing Partner', state: 'WA', country: 'US', company_size: '11-50', budget: '$5k-$15k', service_interest: 'Cybersecurity', timeline: 'ASAP' },
    expect: { counts: { routed: 1, duplicate_dropped: 1 }, by: 'email', email: mail('zoe.carter', 'lakesidelaw.example.com') },
  },
  {
    id: 'TC-18', batch: 'A', title: 'SQL and HTML in input are stored as plain text',
    payload: { event_id: ev('TC-18'), first_name: 'Bobby', last_name: 'Tables', email: mail('bobby.tables', 'injection-test.example.com'), company: "Robert'); DROP TABLE lead_log;--", job_title: 'Analyst', state: 'CO', country: 'US', company_size: '1-10', budget: 'Under $5k', service_interest: 'IT Consulting', timeline: 'Just researching', message: '<script>alert(1)</script>' },
    expect: { event: 'routed', priority: 'Cold', score: 15, pool: 'west', company: "Robert'); DROP TABLE lead_log;--", warning_includes: 'kept out of HubSpot' },
  },
  {
    id: 'TC-19', batch: 'A', title: 'Full name field is split into first and last name',
    payload: { event_id: ev('TC-19'), name: 'Chloe Anne Ramirez', email: mail('chloe.ramirez', 'verdantlabs.example.com'), phone: '(305) 555-0119', company: 'Verdant Labs', job_title: 'Head of IT', state: 'FL', country: 'US', company_size: '51-200', budget: '25k', service_interest: 'Cybersecurity', timeline: '1-3 months' },
    expect: { event: 'routed', priority: 'Hot', score: 90, pool: 'enterprise', lead: { first_name: 'Chloe', last_name: 'Anne Ramirez', budget_band: '$15k-$50k' } },
  },
