    payload: { event_id: ev('TC-20'), first_name: 'Jack', last_name: 'Turner', email: mail('jack.turner', 'oakridgeplumbing.example.com'), phone: '(615) 555-0120', company: 'Oakridge Plumbing', job_title: 'Owner', state: 'Narnia', country: 'US', company_size: '11-50', budget: '$5k-$15k', service_interest: 'Managed IT Support', timeline: '1-3 months' },
    expect: { event: 'routed', priority: 'Warm', score: 45, pool: 'manager', route_type: 'no_territory', rep_id: 'rep_rachel', warning_includes: 'Unknown US state' },
  },
