    repeat: 3,
    payload: { event_id: ev('TC-14'), first_name: 'Grace', last_name: 'Lee', email: mail('grace.lee', 'northpointsystems.example.com'), phone: '(415) 555-0114', company: 'Northpoint Systems', job_title: 'IT Director', state: 'CA', country: 'US', company_size: '201-1000', budget: '$15k-$50k', service_interest: 'Cloud Migration', timeline: '1-3 months' },
    expect: { counts: { routed: 1, duplicate_dropped: 2 }, by: 'event' },
  },
  {
    id: 'TC-17', batch: 'AUTH', title: 'Webhook call with a wrong API key is refused',
    payload: { event_id: ev('TC-17'), first_name: 'Mallory', last_name: 'Intruder', email: mail('mallory', 'attacker.example.com'), company: 'Unknown', service_interest: 'Other' },
    expect: { http_status_in: [401, 403], no_log: true },
  },
  {
    id: 'TC-16', batch: 'C', title: 'Returning contact goes back to the same rep and updates the same CRM contact',
    payload: { event_id: ev('TC-16'), first_name: 'Ava', last_name: 'Martin', email: mail('ava.martin', 'harborviewdental.example.com'), company: 'Harborview Dental Group', state: 'MA', country: 'US', service_interest: 'Cybersecurity', timeline: 'ASAP', message: 'Following up: we also want a security review.' },
    expect: { event: 'routed', route_type: 'returning', same_rep_as: 'TC-01', crm_is_new: false },
