];

return [{ json: { run_id: run, webhook_url: settings.webhook_url, cases } }];

// Emit Batch A
// Sends the test cases tagged with batch "A" to the next HTTP Request node.
// Cases with "repeat" are emitted several times to simulate duplicate deliveries.

const plan = $('Build Test Plan').first().json;
const out = [];
for (const c of plan.cases.filter((x) => x.batch === 'A')) {
  const times = c.repeat || 1;
  for (let n = 1; n <= times; n++) {
    out.push({ json: { test_id: c.id, attempt: n, webhook_url: plan.webhook_url, payload: c.payload } });
  }
}
return out;

// Emit Batch B
// Sends the test cases tagged with batch "B" to the next HTTP Request node.
// Cases with "repeat" are emitted several times to simulate duplicate deliveries.

const plan = $('Build Test Plan').first().json;
const out = [];
for (const c of plan.cases.filter((x) => x.batch === 'B')) {
  const times = c.repeat || 1;
  for (let n = 1; n <= times; n++) {
    out.push({ json: { test_id: c.id, attempt: n, webhook_url: plan.webhook_url, payload: c.payload } });
  }
}
return out;

// Emit Batch AUTH
// Sends the test cases tagged with batch "AUTH" to the next HTTP Request node.
// Cases with "repeat" are emitted several times to simulate duplicate deliveries.

const plan = $('Build Test Plan').first().json;
const out = [];
for (const c of plan.cases.filter((x) => x.batch === 'AUTH')) {
  const times = c.repeat || 1;
  for (let n = 1; n <= times; n++) {
    out.push({ json: { test_id: c.id, attempt: n, webhook_url: plan.webhook_url, payload: c.payload } });
  }
}
return out;

// Emit Batch C
// Sends the test cases tagged with batch "C" to the next HTTP Request node.
// Cases with "repeat" are emitted several times to simulate duplicate deliveries.

const plan = $('Build Test Plan').first().json;
const out = [];
for (const c of plan.cases.filter((x) => x.batch === 'C')) {
  const times = c.repeat || 1;
  for (let n = 1; n <= times; n++) {
    out.push({ json: { test_id: c.id, attempt: n, webhook_url: plan.webhook_url, payload: c.payload } });
  }
}
return out;

// Evaluate Results
// Compares what the router logged for this run against each test case's expected result.

const plan = $('Build Test Plan').first().json;
const run = plan.run_id;
const rows = $('Read Results from Log').all().map((i) => i.json).filter((r) => r && r.event);

// HTTP status of every request, matched back to its test case by position.
const sends = [];
for (const [emitter, sender] of [
  ['Emit Batch A', 'Send Batch A'],
  ['Emit Batch B', 'Send Batch B (parallel)'],
  ['Emit Auth Test', 'Send With Wrong API Key'],
  ['Emit Batch C', 'Send Batch C'],
]) {
  let ins = [];
  let outs = [];
  try { ins = $(emitter).all(); outs = $(sender).all(); } catch (e) { continue; }
  ins.forEach((item, idx) => sends.push({ test_id: item.json.test_id, status: Number(outs[idx]?.json?.statusCode || 0) }));
}

const evId = (id) => `${run}-${id}`;
const rowsFor = (c) => (c.expect.by === 'email'
  ? rows.filter((r) => r.email === c.expect.email)
  : rows.filter((r) => r.source_event_id === evId(c.id)));
const finalRow = (c) => rowsFor(c).find((r) => ['routed', 'unassigned', 'rejected'].includes(r.event));

const results = [];
const add = (id, title, expected, actual, passed) => results.push({ json: { run_id: run, test_id: id, title, expected, actual, passed } });
const fmt = (o) => Object.entries(o).map(([k, v]) => `${k}=${typeof v === 'object' ? JSON.stringify(v) : v}`).join(', ');

for (const c of plan.cases) {
  const e = c.expect;
  if (e.counts) {
    const got = {};
    for (const k of Object.keys(e.counts)) got[k] = rowsFor(c).filter((r) => r.event === k).length;
    add(c.id, c.title, fmt(e.counts), fmt(got), Object.keys(e.counts).every((k) => got[k] === e.counts[k]));
    continue;
  }
  if (e.http_status_in) {
    const statuses = sends.filter((s) => s.test_id === c.id).map((s) => s.status);
    const logged = rowsFor(c).length;
    const ok = statuses.length > 0 && statuses.every((s) => e.http_status_in.includes(s)) && logged === 0;
    add(c.id, c.title, `http_status in ${e.http_status_in.join('/')}, log rows=0`, `http_status=${statuses.join('/') || 'none'}, log rows=${logged}`, ok);
    continue;
  }
  const row = finalRow(c);
  if (!row) {
    add(c.id, c.title, fmt({ event: e.event }), 'No result logged yet (still processing or failed; check n8n executions)', false);
    continue;
  }
  const exp = {};
  const act = {};
  const check = (key, expected, actual) => { exp[key] = expected; act[key] = actual ?? '(blank)'; };
  check('event', e.event, row.event);
  for (const key of ['priority', 'score', 'pool', 'route_type', 'rep_id', 'company']) {
    if (e[key] !== undefined) check(key, e[key], row[key]);
  }
  const lead = row.details?.lead || {};
  for (const [key, value] of Object.entries(e.lead || {})) check(key, value, lead[key]);
  if (e.reason_includes) check('reason contains', e.reason_includes, String(row.reason || '').includes(e.reason_includes) ? e.reason_includes : row.reason);
  if (e.warning_includes) {
    const warnings = (row.details?.warnings || []).join('; ');
    check('warning contains', e.warning_includes, warnings.includes(e.warning_includes) ? e.warning_includes : warnings);
  }
  if (e.crm_is_new !== undefined) check('crm_is_new', e.crm_is_new, row.crm_is_new);
  if (e.same_rep_as) {
    const other = plan.cases.find((x) => x.id === e.same_rep_as);
    const otherRow = other ? finalRow(other) : null;
    check(`same rep as ${e.same_rep_as}`, otherRow?.rep_id || '(none)', row.rep_id);
  }
  const passed = Object.keys(exp).every((k) => String(exp[k]) === String(act[k]));
  add(c.id, c.title, fmt(exp), fmt(act), passed);
}

// TC-21: round-robin balance inside each pool.
const rotated = rows.filter((r) => r.event === 'routed' && ['territory', 'score', 'no_territory', 'fallback'].includes(r.route_type));
const byPool = {};
for (const r of rotated) {
  byPool[r.pool] = byPool[r.pool] || {};
  byPool[r.pool][r.rep_name || r.rep_id] = (byPool[r.pool][r.rep_name || r.rep_id] || 0) + 1;
}
const balanceProblems = [];
for (const pool of ['east', 'west', 'enterprise']) {
  const counts = Object.values(byPool[pool] || {});
  const total = counts.reduce((a, b) => a + b, 0);
  if (total >= 2 && counts.length < 2) balanceProblems.push(`${pool}: only one rep used`);
  if (counts.length && Math.max(...counts) - Math.min(...counts) > 1) balanceProblems.push(`${pool}: uneven`);
}
add('TC-21', 'Round-robin keeps every pool balanced (difference of 1 at most)',
  'east, west and enterprise each split across 2 reps, difference <= 1',
  Object.entries(byPool).map(([p, reps]) => `${p}: ${fmt(reps)}`).join(' | ') + (balanceProblems.length ? ` | PROBLEMS: ${balanceProblems.join('; ')}` : ''),
  balanceProblems.length === 0 && rotated.length > 0);

// TC-22: every valid delivery is acknowledged immediately with 202 Accepted.
const valid = sends.filter((s) => s.test_id !== 'TC-17');
const not202 = valid.filter((s) => s.status !== 202);
add('TC-22', 'Webhook acknowledges every valid delivery with 202 Accepted',
  `${valid.length} of ${valid.length} requests returned 202`,
  `${valid.length - not202.length} of ${valid.length} returned 202${not202.length ? ` (others: ${not202.map((s) => `${s.test_id}=${s.status}`).join(', ')})` : ''}`,
  valid.length > 0 && not202.length === 0);

results.sort((a, b) => a.json.test_id.localeCompare(b.json.test_id));
return results;

// Test Summary
// One line verdict for the run, plus the list of failures to look at.

const results = $('Evaluate Results').all().map((i) => i.json);
const failed = results.filter((r) => !r.passed);
return [{
  json: {
    run_id: results[0]?.run_id,
    verdict: failed.length === 0 ? `ALL ${results.length} TESTS PASSED` : `${failed.length} OF ${results.length} TESTS FAILED`,
    passed: results.length - failed.length,
    failed: failed.length,
    failed_tests: failed.map((r) => `${r.test_id}: ${r.title} | expected ${r.expected} | actual ${r.actual}`),
    where_to_look: 'Full results are in the test_results table (view v_latest_test_run in Adminer).',
  },
}];
